223	// Legal JSON numbers outside the float64 range must be accepted on a success
224	// report at any nesting depth and come back byte-for-byte, never as Infinity,
225	// zero, a string or a rounded value. The idempotent retry rule compares them by
226	// exact decimal value, while malformed JSON or a non-object result stays a 400
227	// that neither completes the task nor occupies the receiptId.
228	func TestTaskReportSuccessKeepsOutOfRangeNumbersExact(t *testing.T) {
229		store, _ := newClockStore()
230		h := NewHandler(store)
231		mustRegister(t, h, "dev-1")
232		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
233		claim := claimTask(t, h, "dev-1", http.StatusOK)
234	
235		// A legal number larger than MaxFloat64 and one smaller than the smallest
236		// positive subnormal, one nested inside an object, are both accepted.
237		large := `{"scale":1e309,"detail":{"offset":1e-400}}`
238		first := reportTask(t, h, "dev-1", claim.Task.ID,
239			reportBody("rcpt-1", claim.Credential, true, "", large), http.StatusCreated)
240		if string(first.Result) != large {
241			t.Fatalf("receipt changed number: %s", first.Result)
242		}
243		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
244		if task.Status != "succeeded" || task.CompletedAt == nil {
245			t.Fatalf("task after success: %+v", task)
246		}
247		if string(task.Result) != large {
248			t.Fatalf("task detail changed number: %s", task.Result)
249		}
250	
251		// Same values in a different notation, key order and whitespace:
252		// 10e308 == 1e309 and 10e-401 == 1e-400 exactly, so it is an idempotent
253		// replay returning the first receipt and its receive time.
254		retry := reportTask(t, h, "dev-1", claim.Task.ID,
255			reportBody("rcpt-1", claim.Credential, true, "",
256				`{ "detail" : { "offset" : 10e-401 } , "scale" : 10e308 }`), http.StatusOK)
257		if string(retry.Result) != large || !retry.ReceivedAt.Equal(first.ReceivedAt) {
258			t.Fatalf("equal-value retry = %+v, want first receipt %+v", retry, first)
259		}
260	
261		// A genuinely different out-of-range value conflicts and leaves the stored
262		// result untouched.
263		reportTask(t, h, "dev-1", claim.Task.ID,
264			reportBody("rcpt-1", claim.Credential, true, "", `{"scale":2e309,"detail":{"offset":1e-400}}`),
265			http.StatusConflict)
266		// A tiny positive number is not zero.
267		reportTask(t, h, "dev-1", claim.Task.ID,
268			reportBody("rcpt-1", claim.Credential, true, "", `{"scale":1e309,"detail":{"offset":0}}`),
269			http.StatusConflict)
270		// Array element order stays significant even with out-of-range elements.
271		reportTask(t, h, "dev-1", claim.Task.ID,
272			reportBody("rcpt-1", claim.Credential, true, "",
273				`{"scale":1e309,"detail":{"offset":1e-400},"steps":[1e309,-1e309]}`), http.StatusConflict)
274		if task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK); string(task.Result) != large {
275			t.Fatalf("conflict rewrote stored result: %s", task.Result)
276		}
277		if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", claim.Task.ID))); got != "created,claimed,succeeded" {
278			t.Fatalf("conflicts appended audit: %s", got)
279		}
280	
281		// An empty object is a valid success result on a fresh task.
282		createTask(t, h, "dev-1", taskBody("req-2", 30), http.StatusCreated)
283		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
284		empty := reportTask(t, h, "dev-1", claim2.Task.ID,
285			reportBody("rcpt-empty", claim2.Credential, true, "", `{}`), http.StatusCreated)
286		if string(empty.Result) != `{}` {
287			t.Fatalf("empty result receipt = %s", empty.Result)
288		}
289		if task = getTask(t, h, "dev-1", claim2.Task.ID, http.StatusOK); task.Status != "succeeded" || string(task.Result) != `{}` {
290			t.Fatalf("empty object task: %+v", task)
291		}
292	}
