294	// Malformed success payloads are rejected with 400 before the store runs: the
295	// task stays in progress under the same credential and deadline, the receiptId
296	// is not occupied, and a corrected submission with the same number is accepted
297	// while the credential and deadline are still valid.
298	func TestTaskReportSuccessRejectsInvalidResultWithoutOccupyingReceipt(t *testing.T) {
299		store, _ := newClockStore()
300		h := NewHandler(store)
301		mustRegister(t, h, "dev-1")
302		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
303		claim := claimTask(t, h, "dev-1", http.StatusOK)
304	
305		for _, body := range []string{
306			// Missing result.
307			`{"receiptId":"rcpt-fix","credential":` + fmt.Sprintf("%q", claim.Credential) + `,"success":true}`,
308			// Top-level array or null instead of an object.
309			reportBody("rcpt-fix", claim.Credential, true, "", `[1e309]`),
310			reportBody("rcpt-fix", claim.Credential, true, "", `null`),
311			// Non-finite spellings are not JSON, including when nested.
312			reportBody("rcpt-fix", claim.Credential, true, "", `{"scale":NaN}`),
313			reportBody("rcpt-fix", claim.Credential, true, "", `{"scale":Infinity}`),
314			reportBody("rcpt-fix", claim.Credential, true, "", `{"scale":-Infinity}`),
315			reportBody("rcpt-fix", claim.Credential, true, "", `{"nested":{"steps":[1e309,NaN]}}`),
316		} {
317			if r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/dev-1/tasks/%d/reports", claim.Task.ID), body); r.Code != http.StatusBadRequest {
318				t.Fatalf("body %s => %d, want 400: %s", body, r.Code, r.Body.String())
319			}
320			if task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK); task.Status != "in_progress" || task.CompletedAt != nil {
321				t.Fatalf("400 completed the task: %+v", task)
322			}
323		}
324	
325		// The number was never bound and the credential/deadline still stand, so
326		// the corrected report with the same receiptId succeeds exactly once.
327		report := reportTask(t, h, "dev-1", claim.Task.ID,
328			reportBody("rcpt-fix", claim.Credential, true, "", `{"scale":1e309,"detail":{"offset":1e-400}}`),
329			http.StatusCreated)
330		if !report.Success || report.ReceiptID != "rcpt-fix" {
331			t.Fatalf("corrected report: %+v", report)
332		}
333		if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", claim.Task.ID))); got != "created,claimed,succeeded" {
334			t.Fatalf("audit = %s, want created,claimed,succeeded", got)
335		}
