338	func TestTaskReportFailureAndBackoff(t *testing.T) {
339		store, clock := newClockStore()
340		h := NewHandler(store)
341		mustRegister(t, h, "dev-1")
342		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
343	
344		// First failure.
345		claim := claimTask(t, h, "dev-1", http.StatusOK)
346		reportTask(t, h, "dev-1", claim.Task.ID,
347			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
348		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
349		if task.Status != "waiting" || task.FailureReason != "disk full" || task.Attempts != 1 {
350			t.Fatalf("after first failure: %+v", task)
351		}
352		if !task.NextClaimableAt.Equal(clock.UTC().Add(1 * time.Second)) {
353			t.Fatalf("next claimable = %s, want +1s", task.NextClaimableAt)
354		}
355		claimTask(t, h, "dev-1", http.StatusNoContent)
356	
357		// After the backoff, claim again.
358		*clock = clock.Add(2 * time.Second)
359		claim = claimTask(t, h, "dev-1", http.StatusOK)
360		if claim.Attempt != 2 {
361			t.Fatalf("attempt = %d, want 2", claim.Attempt)
362		}
363		reportTask(t, h, "dev-1", claim.Task.ID,
364			reportBody("rcpt-2", claim.Credential, false, "still full", ""), http.StatusCreated)
365		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
366		if task.Status != "waiting" || task.Attempts != 2 {
367			t.Fatalf("after second failure: %+v", task)
368		}
369		if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
370			t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
371		}
372	
373		// Third failure ends the task.
374		*clock = clock.Add(3 * time.Second)
375		claim = claimTask(t, h, "dev-1", http.StatusOK)
376		if claim.Attempt != 3 {
377			t.Fatalf("attempt = %d, want 3", claim.Attempt)
378		}
379		reportTask(t, h, "dev-1", claim.Task.ID,
380			reportBody("rcpt-3", claim.Credential, false, "gave up", ""), http.StatusCreated)
381		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
382		if task.Status != "failed" || task.CompletedAt == nil {
383			t.Fatalf("after third failure: %+v", task)
384		}
385		claimTask(t, h, "dev-1", http.StatusNoContent)
386	}
