388	func TestTaskReportFailureRetry(t *testing.T) {
389		store, clock := newClockStore()
390		h := NewHandler(store)
391		mustRegister(t, h, "dev-1")
392		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
393	
394		claim := claimTask(t, h, "dev-1", http.StatusOK)
395		first := reportTask(t, h, "dev-1", claim.Task.ID,
396			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
397		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
398		nextClaimable := task.NextClaimableAt
399	
400		// An identical retry is the received receipt again: 200 with the first
401		// receiptId, reason and receive time.
402		*clock = clock.Add(500 * time.Millisecond)
403		retry := reportTask(t, h, "dev-1", claim.Task.ID,
404			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
405		if retry.ReceiptID != first.ReceiptID || retry.Reason != first.Reason || !retry.ReceivedAt.Equal(first.ReceivedAt) {
406			t.Fatalf("retry = %+v, want the first receipt %+v", retry, first)
407		}
408	
409		// The retry does not accumulate a failure, re-time the wait or add audit.
410		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
411		if task.Status != "waiting" || !task.NextClaimableAt.Equal(nextClaimable) {
412			t.Fatalf("retry changed the task: %+v", task)
413		}
414		audit := listAudit(t, h, "dev-1", claim.Task.ID)
415		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed" {
416			t.Fatalf("audit after retry = %s", got)
417		}
418	
419		// Same receiptId with a changed reason or flipped to success -> 409, and
420		// the stored receipt is untouched.
421		reportTask(t, h, "dev-1", claim.Task.ID,
422			reportBody("rcpt-1", claim.Credential, false, "other reason", ""), http.StatusConflict)
423		reportTask(t, h, "dev-1", claim.Task.ID,
424			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
425		again := reportTask(t, h, "dev-1", claim.Task.ID,
426			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
427		if !again.ReceivedAt.Equal(first.ReceivedAt) || again.Reason != "disk full" {
428			t.Fatalf("receipt after conflicts = %+v", again)
429		}
430	
431		// A new receiptId with the stale credential is rejected and does not take
432		// the receiptId: the same receiptId is accepted once the task is claimed
433		// again and reported with the fresh credential.
434		reportTask(t, h, "dev-1", claim.Task.ID,
435			reportBody("rcpt-2", claim.Credential, false, "too early", ""), http.StatusConflict)
436	
437		// After the backoff the task is claimed again; the old receipt still
438		// replays with the original (now stale) credential and neither the replay
439		// nor a content conflict disturbs the running attempt.
440		*clock = nextClaimable.Add(time.Second)
441		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
442		if claim2.Attempt != 2 {
443			t.Fatalf("re-claim attempt = %d, want 2", claim2.Attempt)
444		}
445		retry = reportTask(t, h, "dev-1", claim.Task.ID,
446			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusOK)
447		if !retry.ReceivedAt.Equal(first.ReceivedAt) {
448			t.Fatalf("retry after re-claim = %+v, want receivedAt %s", retry, first.ReceivedAt)
449		}
450		reportTask(t, h, "dev-1", claim.Task.ID,
451			reportBody("rcpt-1", claim.Credential, false, "changed", ""), http.StatusConflict)
452		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
453		if task.Status != "in_progress" || task.Attempts != 2 || task.Deadline == nil || !task.Deadline.Equal(claim2.Deadline) {
454			t.Fatalf("running attempt disturbed: %+v", task)
455		}
456	
457		// The device reports the new attempt's failure with a fresh receiptId and
458		// the current credential; it joins the usual accumulation and backoff.
459		reportTask(t, h, "dev-1", claim.Task.ID,
460			reportBody("rcpt-2", claim2.Credential, false, "still full", ""), http.StatusCreated)
461		task = getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
462		if task.Status != "waiting" || task.FailureReason != "still full" {
463			t.Fatalf("after second failure: %+v", task)
464		}
465		if !task.NextClaimableAt.Equal(clock.UTC().Add(2 * time.Second)) {
466			t.Fatalf("next claimable = %s, want +2s", task.NextClaimableAt)
467		}
468		audit = listAudit(t, h, "dev-1", claim.Task.ID)
469		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed,claimed,failed" {
470			t.Fatalf("audit = %s", got)
471		}
472	}
