474	// A diagnostic receiptId belongs to exactly one task of a device: once task 1
475	// has accepted it, task 2 of the same device cannot take it as a new receipt,
476	// even with identical content, its own valid credential and time left. The
477	// rejected submission leaves task 2's execution untouched; an unused number
478	// still works, the original receipt still replays on task 1, and another
479	// device accepts the same number independently.
480	func TestTaskReceiptBoundToOneTask(t *testing.T) {
481		store, _ := newClockStore()
482		h := NewHandler(store)
483		mustRegister(t, h, "dev-1")
484		mustRegister(t, h, "dev-2")
485		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
486		claim1 := claimTask(t, h, "dev-1", http.StatusOK)
487		first := reportTask(t, h, "dev-1", claim1.Task.ID,
488			reportBody("shared-rcpt", claim1.Credential, true, "", `{"ok":true,"n":1}`), http.StatusCreated)
489	
490		// Task 2 is claimed next and is still in progress within its deadline with
491		// its own credential.
492		createTask(t, h, "dev-1", taskBody("req-2", 30), http.StatusCreated)
493		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
494		if claim2.Task.ID != 2 {
495			t.Fatalf("second claim took task %d, want 2", claim2.Task.ID)
496		}
497	
498		// Reusing task 1's receipt on task 2 conflicts with identical content...
499		reportTask(t, h, "dev-1", 2,
500			reportBody("shared-rcpt", claim2.Credential, true, "", `{"n":1,"ok":true}`), http.StatusConflict)
501		// ...and with different content just the same.
502		reportTask(t, h, "dev-1", 2,
503			reportBody("shared-rcpt", claim2.Credential, true, "", `{"ok":false}`), http.StatusConflict)
504	
505		// Task 2 keeps its previous execution state, attempts, deadline and
506		// credential, and gains no completion or failure audit record.
507		task2 := getTask(t, h, "dev-1", 2, http.StatusOK)
508		if task2.Status != "in_progress" || task2.Attempts != 1 || task2.CompletedAt != nil {
509			t.Fatalf("conflict disturbed task 2 state: %+v", task2)
510		}
511		if task2.Deadline == nil || !task2.Deadline.Equal(claim2.Deadline) {
512			t.Fatalf("task 2 deadline changed: %+v vs claim %s", task2.Deadline, claim2.Deadline)
513		}
514		if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 2))); got != "created,claimed" {
515			t.Fatalf("task 2 audit after conflict = %s, want created,claimed", got)
516		}
517	
518		// An unused receiptId succeeds on the still-valid execution.
519		reportTask(t, h, "dev-1", 2,
520			reportBody("rcpt-2", claim2.Credential, true, "", `{"ok":true}`), http.StatusCreated)
521		task2 = getTask(t, h, "dev-1", 2, http.StatusOK)
522		if task2.Status != "succeeded" || task2.CompletedAt == nil {
523			t.Fatalf("task 2 after fresh receipt: %+v", task2)
524		}
525		if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 2))); got != "created,claimed,succeeded" {
526			t.Fatalf("task 2 audit = %s", got)
527		}
528	
529		// Task 1 gained nothing from the conflict.
