588	// Failure receipts are bound to one task as well: the waiting task's receipt
589	// can be retried while waiting and after the task finally ends, but cannot be
590	// taken by another task of the same device.
591	func TestTaskFailureReceiptBoundToOneTask(t *testing.T) {
592		store, clock := newClockStore()
593		h := NewHandler(store)
594		mustRegister(t, h, "dev-1")
595		createTask(t, h, "dev-1", taskBody("req-1", 30), http.StatusCreated)
596		claim1 := claimTask(t, h, "dev-1", http.StatusOK)
597		first := reportTask(t, h, "dev-1", 1,
598			reportBody("rc-fail", claim1.Credential, false, "disk full", ""), http.StatusCreated)
599	
600		// The identical failure receipt replays while the task waits.
601		retry := reportTask(t, h, "dev-1", 1,
602			reportBody("rc-fail", claim1.Credential, false, "disk full", ""), http.StatusOK)
603		if !retry.ReceivedAt.Equal(first.ReceivedAt) {
604			t.Fatalf("waiting retry receivedAt = %s, want %s", retry.ReceivedAt, first.ReceivedAt)
605		}
606	
607		// Task 2 is claimed while task 1 waits; the failure receipt number cannot
608		// be submitted to it even with identical content and its own credential.
609		createTask(t, h, "dev-1", taskBody("req-2", 30), http.StatusCreated)
610		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
611		if claim2.Task.ID != 2 {
612			t.Fatalf("second claim took task %d, want 2", claim2.Task.ID)
613		}
614		reportTask(t, h, "dev-1", 2,
615			reportBody("rc-fail", claim2.Credential, false, "disk full", ""), http.StatusConflict)
616		task2 := getTask(t, h, "dev-1", 2, http.StatusOK)
617		if task2.Status != "in_progress" || task2.Attempts != 1 || task2.FailureReason != "" {
618			t.Fatalf("conflict disturbed task 2: %+v", task2)
619		}
620		if task2.Deadline == nil || !task2.Deadline.Equal(claim2.Deadline) {
621			t.Fatalf("task 2 deadline changed: %+v", task2.Deadline)
622		}
623		// An unused number finishes task 2 normally.
624		reportTask(t, h, "dev-1", 2,
625			reportBody("rc-other", claim2.Credential, true, "", `{"ok":true}`), http.StatusCreated)
626	
627		// Drive task 1 through its remaining attempts to a final failure.
628		*clock = clock.Add(2 * time.Second)
629		claim1 = claimTask(t, h, "dev-1", http.StatusOK)
630		if claim1.Task.ID != 1 || claim1.Attempt != 2 {
631			t.Fatalf("re-claim = task %d attempt %d, want task 1 attempt 2", claim1.Task.ID, claim1.Attempt)
632		}
633		reportTask(t, h, "dev-1", 1,
634			reportBody("rc-fail-2", claim1.Credential, false, "still full", ""), http.StatusCreated)
635		*clock = clock.Add(3 * time.Second)
636		claim1 = claimTask(t, h, "dev-1", http.StatusOK)
637		reportTask(t, h, "dev-1", 1,
638			reportBody("rc-fail-3", claim1.Credential, false, "gave up", ""), http.StatusCreated)
639		if task := getTask(t, h, "dev-1", 1, http.StatusOK); task.Status != "failed" {
640			t.Fatalf("task 1 should be failed: %+v", task)
641		}
642	
643		// After the task has ended, the original receipt still replays with its
644		// first receive time and adds no new failure.
645		again := reportTask(t, h, "dev-1", 1,
646			reportBody("rc-fail", claim1.Credential, false, "disk full", ""), http.StatusOK)
647		if again.Reason != "disk full" || !again.ReceivedAt.Equal(first.ReceivedAt) {
648			t.Fatalf("post-end retry = %+v, want first receipt %+v", again, first)
649		}
650		if got := joinEvents(eventsOf(listAudit(t, h, "dev-1", 1))); got != "created,claimed,failed,claimed,failed,claimed,failed" {
651			t.Fatalf("task 1 audit = %s", got)
652		}
653	}
