910	// Reported failures and deadline timeouts accumulate into one failure count
911	// with one set of backoff/end rules, while their timestamps, reasons and audit
912	// events stay distinct.
913	func TestTaskFailuresAccumulateAcrossSources(t *testing.T) {
914		store, clock := newClockStore()
915		h := NewHandler(store)
916		mustRegister(t, h, "dev-1")
917		createTask(t, h, "dev-1", taskBody("req-1", 1), http.StatusCreated)
918	
919		// Failure 1: device-reported; the wait runs from the receipt time.
920		claim := claimTask(t, h, "dev-1", http.StatusOK)
921		reportTask(t, h, "dev-1", claim.Task.ID,
922			reportBody("rcpt-1", claim.Credential, false, "disk full", ""), http.StatusCreated)
923		task := getTask(t, h, "dev-1", claim.Task.ID, http.StatusOK)
924		if task.Status != "waiting" || task.FailureReason != "disk full" || task.Attempts != 1 {
925			t.Fatalf("after first failure: %+v", task)
926		}
927		if !task.NextClaimableAt.Equal(clock.UTC().Add(1 * time.Second)) {
928			t.Fatalf("next claimable = %s, want receipt time +1s", task.NextClaimableAt)
929		}
930		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 1 {
931			t.Fatalf("failures = %d, want 1", got)
932		}
933	
934		// The waiting task does not block another already-claimable task.
935		createTask(t, h, "dev-1", taskBody("req-other", 60), http.StatusCreated)
936		other := claimTask(t, h, "dev-1", http.StatusOK)
937		if other.Task.ID != 2 {
938			t.Fatalf("claim during backoff took task %d, want 2", other.Task.ID)
939		}
940		reportTask(t, h, "dev-1", other.Task.ID,
941			reportBody("rcpt-other", other.Credential, true, "", `{"ok":true}`), http.StatusCreated)
942	
943		// Failure 2: a timeout. It takes the 2-second backoff because the failure
944		// count is shared, and the wait runs from the deadline rather than the
945		// (much later) query time.
946		*clock = clock.Add(2 * time.Second)
947		claim = claimTask(t, h, "dev-1", http.StatusOK)
948		if claim.Attempt != 2 || claim.Task.ID != 1 {
949			t.Fatalf("re-claim = %+v, want task 1 attempt 2", claim)
950		}
951		deadline2 := claim.Deadline
952		*clock = clock.Add(4 * time.Second)
953		task = getTask(t, h, "dev-1", 1, http.StatusOK)
954		if task.Status != "waiting" || task.FailureReason != "deadline exceeded" {
955			t.Fatalf("after timeout: %+v", task)
956		}
957		if !task.NextClaimableAt.Equal(deadline2.Add(2 * time.Second)) {
958			t.Fatalf("next claimable = %s, want deadline +2s (shared failure 2)", task.NextClaimableAt)
959		}
960		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 2 {
961			t.Fatalf("failures = %d, want 2", got)
962		}
963		// The timed-out credential no longer authorizes a receipt.
964		reportTask(t, h, "dev-1", 1,
965			reportBody("rcpt-late", claim.Credential, true, "", `{"ok":true}`), http.StatusConflict)
966		// Repeated queries neither re-time the task nor accumulate another failure.
967		getTask(t, h, "dev-1", 1, http.StatusOK)
968		if got := store.devices["dev-1"].tasks[0].task.Failures; got != 2 {
969			t.Fatalf("repeat query changed failures to %d", got)
970		}
971		if got := len(store.devices["dev-1"].tasks[0].audit); got != 5 {
972			t.Fatalf("audit length after repeat query = %d, want 5", got)
973		}
974	
975		// Failure 3: a reported failure ends the task, stamped at receipt time.
976		claim = claimTask(t, h, "dev-1", http.StatusOK)
977		if claim.Attempt != 3 {
978			t.Fatalf("attempt = %d, want 3", claim.Attempt)
979		}
980		reportTask(t, h, "dev-1", 1,
981			reportBody("rcpt-3", claim.Credential, false, "gave up", ""), http.StatusCreated)
982		task = getTask(t, h, "dev-1", 1, http.StatusOK)
983		if task.Status != "failed" || task.CompletedAt == nil || task.Attempts != 3 {
984			t.Fatalf("after third failure: %+v", task)
985		}
986		if !task.CompletedAt.Equal(clock.UTC()) {
987			t.Fatalf("completedAt = %s, want receipt time %s", task.CompletedAt, clock.UTC())
988		}
989		claimTask(t, h, "dev-1", http.StatusNoContent)
990	
991		// The audit keeps both sources distinct, dated and ordered.
992		audit := listAudit(t, h, "dev-1", 1)
993		if got := joinEvents(eventsOf(audit)); got != "created,claimed,failed,claimed,timed_out,claimed,failed" {
994			t.Fatalf("audit events = %s", got)
995		}
996		timedOut := audit[4]
997		if timedOut.Event != "timed_out" || timedOut.At != deadline2 || timedOut.Reason != "deadline exceeded" ||
998			timedOut.Attempt != 2 || timedOut.FromStatus != "in_progress" || timedOut.ToStatus != "waiting" {
999			t.Fatalf("timeout audit record = %+v", timedOut)
1000		}
1001		if audit[2].At.IsZero() || audit[6].ToStatus != "failed" {
1002			t.Fatalf("reported failure audit records = %+v / %+v", audit[2], audit[6])
1003		}
1004	}
1005	
1006	// An attempt is live exactly up to and including its deadline; only a strictly
1007	// later instant is a timeout.
1008	func TestTaskDeadlineBoundary(t *testing.T) {
1009		store, _ := newClockStore()
1010		h := NewHandler(store)
1011		mustRegister(t, h, "dev-1")
1012		createTask(t, h, "dev-1", taskBody("req-1", 5), http.StatusCreated)
1013		claim := claimTask(t, h, "dev-1", http.StatusOK)
1014		deadline := claim.Deadline
1015	
1016		// Exactly at the deadline the attempt is still in progress...
1017		store.now = func() time.Time { return deadline }
1018		if task := getTask(t, h, "dev-1", 1, http.StatusOK); task.Status != "in_progress" {
1019			t.Fatalf("at the deadline status = %s, want in_progress", task.Status)
1020		}
1021		// ...and a report presented exactly then is accepted with the credential.
1022		reportTask(t, h, "dev-1", 1,
1023			reportBody("rcpt-1", claim.Credential, true, "", `{"ok":true}`), http.StatusCreated)
1024	
1025		// A strictly later instant expires a fresh attempt.
1026		createTask(t, h, "dev-1", taskBody("req-2", 5), http.StatusCreated)
1027		claim2 := claimTask(t, h, "dev-1", http.StatusOK)
1028		store.now = func() time.Time { return claim2.Deadline.Add(time.Second) }
1029		task := getTask(t, h, "dev-1", claim2.Task.ID, http.StatusOK)
1030		if task.Status != "waiting" || !task.NextClaimableAt.Equal(claim2.Deadline.Add(1*time.Second)) {
1031			t.Fatalf("past the deadline: %+v", task)
1032		}
1033	}
