	createTask(t, h, "dev-1", taskBody("req-4", 30), http.StatusCreated)
	claim = claimTask(t, h, "dev-1", http.StatusOK)
	reportTask(t, h, "dev-1", claim.Task.ID,
		reportBody("rcpt-2", claim.Credential, false, "nope", ""), http.StatusCreated)
