171		if errors.Is(err, ErrStorageUnavailable) {
172			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
173			return
174		}
175		if err != nil {
176			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
177			return
178		}
179		status := http.StatusAccepted
180		if repeat {
181			status = http.StatusOK
182		}
183		writeJSON(w, status, receipt)
