272		writeJSON(w, http.StatusOK, map[string]any{
273			"deviceId":   id,
274			"events":     events,
275			"nextCursor": nextCursor,
276		})
277	}
278	
279	func (h *handler) snapshot(w http.ResponseWriter, _ *http.Request) {
280		writeJSON(w, http.StatusOK, map[string]any{"devices": h.store.Snapshot()})
281	}
282	
283	// --- history retention ------------------------------------------------------
284	
285	func (h *handler) getRetention(w http.ResponseWriter, r *http.Request) {
286		status, err := h.store.GetRetention(r.PathValue("id"))
287		if errors.Is(err, ErrDeviceNotFound) {
288			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
289			return
290		}
291		if err != nil {
292			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
293			return
294		}
295		writeJSON(w, http.StatusOK, status)
296	}
297	
298	func (h *handler) setRetention(w http.ResponseWriter, r *http.Request) {
299		var request struct {
300			MaxEvents *int64 `json:"maxEvents"`
301		}
302		if err := decodeSingleJSON(r, &request); err != nil || request.MaxEvents == nil {
303			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "maxEvents is required as a single integer"})
304			return
305		}
306		maxEvents := *request.MaxEvents
307		if maxEvents < 0 || maxEvents > maxRetentionEvents {
308			writeJSON(w, http.StatusBadRequest, map[string]string{
309				"error": fmt.Sprintf("maxEvents must be between 0 and %d", maxRetentionEvents),
310			})
311			return
312		}
313		status, err := h.store.SetRetention(r.PathValue("id"), maxEvents)
314		if errors.Is(err, ErrDeviceNotFound) {
315			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
316			return
317		}
318		if errors.Is(err, ErrStorageUnavailable) {
319			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
320			return
321		}
322		if err != nil {
323			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
324			return
325		}
326		writeJSON(w, http.StatusOK, status)
327	}
328	
329	// --- rules ------------------------------------------------------------------
330	
331	func (h *handler) createRule(w http.ResponseWriter, r *http.Request) {
332		var request struct {
333			ID      string  `json:"id"`
334			Metric  string  `json:"metric"`
335			Trigger float64 `json:"trigger"`
336			Recover float64 `json:"recover"`
337		}
338		if err := decodeJSON(r, &request); err != nil {
339			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
340			return
341		}
342		ruleID := strings.TrimSpace(request.ID)
343		metric := strings.TrimSpace(request.Metric)
344		if ruleID == "" {
345			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "id is required"})
346			return
347		}
348		if metric == "" {
349			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric is required"})
350			return
351		}
352		if !finiteFloat(request.Trigger) || !finiteFloat(request.Recover) {
353			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "thresholds must be finite numbers"})
354			return
355		}
356		if request.Recover >= request.Trigger {
357			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
358			return
359		}
360		rule, err := h.store.CreateRule(r.PathValue("id"), ruleID, metric, request.Trigger, request.Recover)
361		if errors.Is(err, ErrDeviceNotFound) {
362			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
363			return
364		}
365		if errors.Is(err, ErrRuleConflict) {
366			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
367			return
368		}
369		if errors.Is(err, ErrStorageUnavailable) {
370			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
371			return
372		}
373		if err != nil {
374			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
375			return
376		}
377		writeJSON(w, http.StatusCreated, rule)
378	}
379	
380	func (h *handler) listRules(w http.ResponseWriter, r *http.Request) {
381		rules, err := h.store.ListRules(r.PathValue("id"))
382		if errors.Is(err, ErrDeviceNotFound) {
383			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
384			return
385		}
386		if err != nil {
387			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
388			return
389		}
390		writeJSON(w, http.StatusOK, map[string]any{"rules": rules})
391	}
392	
393	func (h *handler) getRule(w http.ResponseWriter, r *http.Request) {
394		rule, err := h.store.GetRule(r.PathValue("id"), r.PathValue("ruleId"))
395		if errors.Is(err, ErrDeviceNotFound) {
396			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
397			return
398		}
399		if errors.Is(err, ErrRuleNotFound) {
400			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
401			return
402		}
403		if err != nil {
404			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
405			return
406		}
407		writeJSON(w, http.StatusOK, rule)
408	}
409	
410	func (h *handler) updateRule(w http.ResponseWriter, r *http.Request) {
411		var request struct {
412			Metric  *string  `json:"metric"`
413			Trigger *float64 `json:"trigger"`
414			Recover *float64 `json:"recover"`
415			Enabled *bool    `json:"enabled"`
416			Version int64    `json:"version"`
417		}
418		if err := decodeJSON(r, &request); err != nil {
419			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "request body must be a single valid JSON object"})
420			return
421		}
422		if request.Version < 1 {
423			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "version is required"})
424			return
425		}
426		if request.Metric != nil && strings.TrimSpace(*request.Metric) == "" {
427			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "metric must not be blank"})
428			return
429		}
430		if request.Trigger != nil && !finiteFloat(*request.Trigger) {
431			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "trigger must be a finite number"})
432			return
433		}
434		if request.Recover != nil && !finiteFloat(*request.Recover) {
435			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover must be a finite number"})
436			return
437		}
438		update := ruleUpdate{}
439		if request.Metric != nil {
440			metric := strings.TrimSpace(*request.Metric)
441			update.Metric = &metric
442		}
443		if request.Trigger != nil {
444			update.Trigger = request.Trigger
445		}
446		if request.Recover != nil {
447			update.Recover = request.Recover
448		}
449		if request.Enabled != nil {
450			update.Enabled = request.Enabled
451		}
452		rule, _, err := h.store.UpdateRule(r.PathValue("id"), r.PathValue("ruleId"), update, request.Version)
453		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrRuleNotFound) {
454			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
455			return
456		}
457		if errors.Is(err, ErrVersionConflict) {
458			writeJSON(w, http.StatusConflict, map[string]string{"error": err.Error()})
459			return
460		}
461		if errors.Is(err, ErrInvalidRule) {
462			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "recover threshold must be less than trigger threshold"})
463			return
464		}
465		if errors.Is(err, ErrStorageUnavailable) {
466			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
467			return
468		}
469		if err != nil {
470			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
471			return
472		}
473		writeJSON(w, http.StatusOK, rule)
474	}
475	
476	// --- alerts -----------------------------------------------------------------
477	
478	func (h *handler) listAlerts(w http.ResponseWriter, r *http.Request) {
479		query := r.URL.Query()
480		filter := AlertFilter{RuleID: strings.TrimSpace(query.Get("ruleId"))}
481		if raw := strings.TrimSpace(query.Get("status")); raw != "" {
482			if raw != alertStatusActive && raw != alertStatusEnded {
483				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "status must be active or ended"})
484				return
485			}
486			filter.Status = raw
487		}
488		if raw := strings.TrimSpace(query.Get("acknowledged")); raw != "" {
489			switch raw {
490			case "true", "1":
491				v := true
492				filter.Acknowledged = &v
493			case "false", "0":
494				v := false
495				filter.Acknowledged = &v
496			default:
497				writeJSON(w, http.StatusBadRequest, map[string]string{"error": "acknowledged must be true or false"})
498				return
499			}
500		}
501		alerts, err := h.store.ListAlerts(r.PathValue("id"), filter)
502		if errors.Is(err, ErrDeviceNotFound) {
503			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
504			return
505		}
506		if errors.Is(err, ErrRuleNotFound) {
507			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
508			return
509		}
510		if err != nil {
511			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
512			return
513		}
514		writeJSON(w, http.StatusOK, map[string]any{"alerts": alerts})
515	}
516	
517	func (h *handler) ackAlert(w http.ResponseWriter, r *http.Request) {
518		alertID, err := strconv.ParseInt(r.PathValue("alertId"), 10, 64)
519		if err != nil || alertID < 1 {
520			writeJSON(w, http.StatusBadRequest, map[string]string{"error": "alertId must be a positive integer"})
521			return
522		}
523		alert, err := h.store.AckAlert(r.PathValue("id"), alertID)
524		if errors.Is(err, ErrDeviceNotFound) || errors.Is(err, ErrAlertNotFound) {
525			writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})
526			return
527		}
528		if errors.Is(err, ErrStorageUnavailable) {
529			writeJSON(w, http.StatusServiceUnavailable, map[string]string{"error": err.Error()})
530			return
531		}
532		if err != nil {
533			writeJSON(w, http.StatusInternalServerError, map[string]string{"error": err.Error()})
534			return
535		}
536		writeJSON(w, http.StatusOK, alert)
537	}
538	
539	func finiteFloat(value float64) bool {
540		return !math.IsNaN(value) && !math.IsInf(value, 0)
541	}
542	
543	func hasBlankKey(values map[string]*float64) bool {
544		for key := range values {
545			if strings.TrimSpace(key) == "" {
546				return true
547			}
548		}
549		return false
550	}
551	
552	// metricValues converts decoded metric values to plain floats. Decoding into
553	// *float64 keeps JSON null distinguishable from a real 0: a null decodes to a
554	// nil pointer and is rejected here instead of being silently stored as 0.
555	// Non-finite numbers are rejected as before.
556	func metricValues(raw map[string]*float64) (map[string]float64, bool) {
557		values := make(map[string]float64, len(raw))
558		for key, value := range raw {
559			if value == nil || !finiteFloat(*value) {
560				return nil, false
561			}
562			values[key] = *value
563		}
564		return values, true
565	}
566	
567	func decodeJSON(r *http.Request, target any) error {
568		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
569		decoder.DisallowUnknownFields()
570		return decoder.Decode(target)
571	}
572	
573	// decodeSingleJSON requires the body to be exactly one JSON value, rejecting
574	// trailing data such as a second JSON object or concatenated documents.
575	func decodeSingleJSON(r *http.Request, target any) error {
576		decoder := json.NewDecoder(http.MaxBytesReader(nil, r.Body, 1<<20))
577		decoder.DisallowUnknownFields()
578		if err := decoder.Decode(target); err != nil {
579			return err
580		}
581		var trailing any
582		if err := decoder.Decode(&trailing); !errors.Is(err, io.EOF) {
583			return errors.New("body must contain a single JSON value")
584		}
585		return nil
586	}
587	
588	func writeJSON(w http.ResponseWriter, status int, value any) {
589		w.Header().Set("Content-Type", "application/json")
590		w.WriteHeader(status)
591		_ = json.NewEncoder(w).Encode(value)
592	}
