1	package fleet
2	
3	// Regression coverage for remote diagnostic task result reporting: a
4	// diagnostic outcome belongs to its task only and must never be mistaken for
5	// device telemetry. Reporting a success (whose result reuses telemetry metric
6	// names) or a failure keeps every device's lastSeenAt, lastTelemetry and
7	// telemetry history exactly as they were, on both the reporting device and the
8	// other registered device. A wrong credential is 409, a successful report whose
9	// result is an array is 400, neither ends the task or saves anything, and a
10	// later live telemetry sample is accepted normally with the next contiguous
11	// receive sequence.
12	
13	import (
14		"fmt"
15		"net/http"
16		"testing"
17		"time"
18	)
19	
20	// snapshotDevice is one device entry from GET /v1/fleet.
21	type snapshotDevice struct {
22		ID            string             `json:"id"`
23		LastSeenAt    time.Time          `json:"lastSeenAt"`
24		LastTelemetry map[string]float64 `json:"lastTelemetry"`
25	}
26	
27	func fleetSnapshot(t *testing.T, h http.Handler) map[string]snapshotDevice {
28		t.Helper()
29		snapshot := decodeBody[struct {
30			Devices []snapshotDevice `json:"devices"`
31		}](t, doRequest(t, h, http.MethodGet, "/v1/fleet", ""))
32		byID := make(map[string]snapshotDevice, len(snapshot.Devices))
33		for _, device := range snapshot.Devices {
34			byID[device.ID] = device
35		}
36		return byID
37	}
38	
39	// historySample is one retained telemetry sample as returned by the history API.
40	type historySample struct {
41		Sequence   int64              `json:"sequence"`
42		ObservedAt time.Time          `json:"observedAt"`
43		Values     map[string]float64 `json:"values"`
44	}
45	
46	func deviceHistory(t *testing.T, h http.Handler, id string) []historySample {
47		t.Helper()
48		page := decodeBody[struct {
49			Events []historySample `json:"events"`
50		}](t, doRequest(t, h, http.MethodGet, fmt.Sprintf("/v1/devices/%s/history?limit=100", id), ""))
51		return page.Events
52	}
53	
54	func assertTelemetryUnchanged(t *testing.T, h http.Handler, want map[string]snapshotDevice, wantHistory map[string][]historySample) {
55		t.Helper()
56		got := fleetSnapshot(t, h)
57		for id, before := range want {
58			after, ok := got[id]
59			if !ok {
60				t.Fatalf("device %s disappeared from the fleet snapshot", id)
61			}
62			if !after.LastSeenAt.Equal(before.LastSeenAt) {
63				t.Fatalf("device %s lastSeenAt changed: %s -> %s", id, before.LastSeenAt, after.LastSeenAt)
64			}
65			if len(after.LastTelemetry) != len(before.LastTelemetry) {
66				t.Fatalf("device %s lastTelemetry length changed: %v -> %v", id, before.LastTelemetry, after.LastTelemetry)
67			}
68			for key, value := range before.LastTelemetry {
69				if other, ok := after.LastTelemetry[key]; !ok || other != value {
70					t.Fatalf("device %s lastTelemetry[%q] changed: %v -> %v", id, key, value, after.LastTelemetry[key])
71				}
72			}
73			events := deviceHistory(t, h, id)
74			if len(events) != len(wantHistory[id]) {
75				t.Fatalf("device %s history length changed: %d -> %d (%+v)", id, len(wantHistory[id]), len(events), events)
76			}
77			for i, wantEvent := range wantHistory[id] {
78				gotEvent := events[i]
79				if gotEvent.Sequence != wantEvent.Sequence || !gotEvent.ObservedAt.Equal(wantEvent.ObservedAt) ||
80					!sameValues(gotEvent.Values, wantEvent.Values) {
81					t.Fatalf("device %s history sample %d changed: %+v -> %+v", id, i, wantEvent, gotEvent)
82				}
83			}
84		}
85	}
86	
87	// TestTaskReportsNeverTouchDeviceTelemetry walks the full scenario: two
88	// registered devices with distinct telemetry, a successful diagnostic report
89	// and a failed one on the target device, the two direct rejection cases, and
90	// finally a fresh live telemetry sample. Throughout, task results stay on the
91	// task and both devices' telemetry state stays intact.
92	func TestTaskReportsNeverTouchDeviceTelemetry(t *testing.T) {
93		store, clock := newClockStore()
94		h := NewHandler(store)
95		mustRegister(t, h, "target")
96		mustRegister(t, h, "other")
97	
98		// Two distinct telemetry samples, one per device. The target's carries the
99		// temperature and battery metrics that the later diagnostic result will
100		// deliberately reuse with different values.
101		*clock = clock.Add(1 * time.Second)
102		targetSeen := clock.UTC()
103		if r := doRequest(t, h, http.MethodPost, "/v1/devices/target/telemetry", `{"temperature":23.5,"battery":91}`); r.Code != http.StatusAccepted {
104			t.Fatalf("target telemetry = %d: %s", r.Code, r.Body.String())
105		}
106		*clock = clock.Add(1 * time.Second)
107		otherSeen := clock.UTC()
108		if r := doRequest(t, h, http.MethodPost, "/v1/devices/other/telemetry", `{"temperature":18.0,"battery":77,"humidity":40}`); r.Code != http.StatusAccepted {
109			t.Fatalf("other telemetry = %d: %s", r.Code, r.Body.String())
110		}
111	
112		wantSnapshot := map[string]snapshotDevice{
113			"target": {
114				ID:            "target",
115				LastSeenAt:    targetSeen,
116				LastTelemetry: map[string]float64{"temperature": 23.5, "battery": 91},
117			},
118			"other": {
119				ID:            "other",
120				LastSeenAt:    otherSeen,
121				LastTelemetry: map[string]float64{"temperature": 18.0, "battery": 77, "humidity": 40},
122			},
123		}
124		wantHistory := map[string][]historySample{
125			"target": {{
126				Sequence:   1,
127				ObservedAt: targetSeen,
128				Values:     map[string]float64{"temperature": 23.5, "battery": 91},
129			}},
130			"other": {{
131				Sequence:   1,
132				ObservedAt: otherSeen,
133				Values:     map[string]float64{"temperature": 18.0, "battery": 77, "humidity": 40},
134			}},
135		}
136	
137		// Sanity-check the seeded fleet state before any task activity.
138		assertTelemetryUnchanged(t, h, wantSnapshot, wantHistory)
139	
140		// --- task 1: claimed, then reported successful with telemetry-named, -----
141		// differently-valued result fields (temperature 99, battery 0). ----------
142		createTask(t, h, "target", taskBody("diag-success", 30), http.StatusCreated)
143		claim := claimTask(t, h, "target", http.StatusOK)
144		if claim.Task.ID != 1 || claim.Attempt != 1 || claim.Credential == "" {
145			t.Fatalf("unexpected claim: %+v", claim)
146		}
147	
148		*clock = clock.Add(5 * time.Second)
149		completedAt := clock.UTC()
150		successResult := `{"temperature":99,"battery":0}`
151		report := reportTask(t, h, "target", claim.Task.ID,
152			reportBody("diag-rc-success", claim.Credential, true, "", successResult), http.StatusCreated)
153		if !report.Success || report.ReceiptID != "diag-rc-success" || !report.ReceivedAt.Equal(completedAt) {
154			t.Fatalf("success report = %+v, want receivedAt %s", report, completedAt)
155		}
156		if string(report.Result) != successResult {
157			t.Fatalf("success report result = %s, want %s", report.Result, successResult)
158		}
159	
160		succeeded := getTask(t, h, "target", claim.Task.ID, http.StatusOK)
161		if succeeded.Status != taskStatusSucceeded {
162			t.Fatalf("task status = %q, want succeeded", succeeded.Status)
163		}
164		if succeeded.CompletedAt == nil || !succeeded.CompletedAt.Equal(completedAt) {
165			t.Fatalf("task completedAt = %+v, want %s", succeeded.CompletedAt, completedAt)
166		}
167		if string(succeeded.Result) != successResult {
168			t.Fatalf("saved task result = %s, want %s", succeeded.Result, successResult)
169		}
170		if got := joinEvents(eventsOf(listAudit(t, h, "target", claim.Task.ID))); got != "created,claimed,succeeded" {
171			t.Fatalf("success task audit = %s, want created,claimed,succeeded", got)
172		}
173	
174		// The success result is diagnostic data, not telemetry: the target's
175		// lastSeenAt/lastTelemetry and its single history sample are unchanged
176		// (temperature stays 23.5, battery 91), and the other device is untouched.
177		assertTelemetryUnchanged(t, h, wantSnapshot, wantHistory)
178	
179		// --- task 2: first execution, reported failed with a non-empty reason ----
180		createTask(t, h, "target", taskBody("diag-failure", 30), http.StatusCreated)
181		claim2 := claimTask(t, h, "target", http.StatusOK)
182		if claim2.Task.ID != 2 || claim2.Attempt != 1 {
183			t.Fatalf("second claim = %+v, want task 2 attempt 1", claim2)
184		}
185	
186		*clock = clock.Add(5 * time.Second)
187		failureAt := clock.UTC()
188		failed := reportTask(t, h, "target", claim2.Task.ID,
189			reportBody("diag-rc-failure", claim2.Credential, false, "sensor unreachable", ""), http.StatusCreated)
190		if failed.Success || failed.Reason != "sensor unreachable" || !failed.ReceivedAt.Equal(failureAt) {
191			t.Fatalf("failure report = %+v, want reason %q receivedAt %s", failed, "sensor unreachable", failureAt)
192		}
193	
194		waiting := getTask(t, h, "target", claim2.Task.ID, http.StatusOK)
195		if waiting.Status != taskStatusWaiting {
196			t.Fatalf("task status = %q, want waiting", waiting.Status)
197		}
198		if waiting.FailureReason != "sensor unreachable" {
199			t.Fatalf("failure reason = %q, want %q", waiting.FailureReason, "sensor unreachable")
200		}
201		if waiting.CompletedAt != nil {
202			t.Fatalf("waiting task carries completedAt: %s", waiting.CompletedAt)
203		}
204		if got := joinEvents(eventsOf(listAudit(t, h, "target", claim2.Task.ID))); got != "created,claimed,failed" {
205			t.Fatalf("failure task audit = %s, want created,claimed,failed", got)
206		}
207	
208		// The reported failure neither refreshes lastSeenAt, overwrites
209		// lastTelemetry nor appends a telemetry sample, on either device.
210		assertTelemetryUnchanged(t, h, wantSnapshot, wantHistory)
211	
212		// --- task 3: the two direct rejections, both within the deadline with ----
213		// receipt numbers that have never been accepted. -------------------------
214		createTask(t, h, "target", taskBody("diag-reject", 30), http.StatusCreated)
215		claim3 := claimTask(t, h, "target", http.StatusOK)
216		if claim3.Task.ID != 3 || claim3.Attempt != 1 {
217			t.Fatalf("third claim = %+v, want task 3 attempt 1", claim3)
218		}
219	
220		// Wrong credential with a fresh receipt number -> 409.
221		reportTask(t, h, "target", claim3.Task.ID,
222			reportBody("diag-rc-wrong-cred", "not-the-current-credential", true, "", `{"ok":true}`), http.StatusConflict)
223		// Current credential but an array result on a success -> 400.
224		reportTask(t, h, "target", claim3.Task.ID,
225			reportBody("diag-rc-array-result", claim3.Credential, true, "", `[{"temperature":99}]`), http.StatusBadRequest)
226	
227		// Neither rejection ends the task, saves a result, or advances the audit
228		// trail beyond the claim.
229		rejected := getTask(t, h, "target", claim3.Task.ID, http.StatusOK)
230		if rejected.Status != taskStatusInProgress {
231			t.Fatalf("rejected task status = %q, want in_progress", rejected.Status)
232		}
233		if rejected.Attempts != 1 || rejected.CompletedAt != nil || len(rejected.Result) != 0 {
234			t.Fatalf("rejections changed the task: %+v", rejected)
235		}
236		if rejected.Deadline == nil || !rejected.Deadline.Equal(claim3.Deadline) {
237			t.Fatalf("rejected task deadline = %+v, want %s", rejected.Deadline, claim3.Deadline)
238		}
239		if got := joinEvents(eventsOf(listAudit(t, h, "target", claim3.Task.ID))); got != "created,claimed" {
240			t.Fatalf("rejected task audit = %s, want created,claimed", got)
241		}
242		// No receipt was saved and neither number was bound by the rejections.
243		ts3 := store.devices["target"].tasks[claim3.Task.ID-1]
244		if len(ts3.reports) != 0 {
245			t.Fatalf("rejections saved reports: %+v", ts3.reports)
246		}
247		for _, receiptID := range []string{"diag-rc-wrong-cred", "diag-rc-array-result"} {
248			if _, bound := store.devices["target"].taskReceipts[receiptID]; bound {
249				t.Fatalf("rejection bound receipt number %q", receiptID)
250			}
251		}
252	
253		// Existing telemetry state is still exactly as seeded.
254		assertTelemetryUnchanged(t, h, wantSnapshot, wantHistory)
255	
256		// --- a later live telemetry sample lands normally on the target ---------
257		*clock = clock.Add(10 * time.Second)
258		newSeen := clock.UTC()
259		if r := doRequest(t, h, http.MethodPost, "/v1/devices/target/telemetry", `{"temperature":24.0,"battery":88}`); r.Code != http.StatusAccepted {
260			t.Fatalf("later telemetry = %d, want 202: %s", r.Code, r.Body.String())
261		}
262	
263		snapshot := fleetSnapshot(t, h)
264		targetAfter := snapshot["target"]
265		if !targetAfter.LastSeenAt.Equal(newSeen) {
266			t.Fatalf("target lastSeenAt after live telemetry = %s, want %s", targetAfter.LastSeenAt, newSeen)
267		}
268		if targetAfter.LastTelemetry["temperature"] != 24.0 || targetAfter.LastTelemetry["battery"] != 88 {
269			t.Fatalf("target lastTelemetry after live telemetry = %v, want temperature 24, battery 88", targetAfter.LastTelemetry)
270		}
271	
272		// History gains exactly the next contiguous sample (sequence 2); the
273		// diagnostic results never entered it.
274		events := deviceHistory(t, h, "target")
275		if len(events) != 2 {
276			t.Fatalf("target history after live telemetry has %d samples, want 2: %+v", len(events), events)
277		}
278		if events[0].Sequence != 1 || events[1].Sequence != 2 {
279			t.Fatalf("target history sequences = %d,%d, want 1,2", events[0].Sequence, events[1].Sequence)
280		}
281		if !events[1].ObservedAt.Equal(newSeen) || !sameValues(events[1].Values, map[string]float64{"temperature": 24.0, "battery": 88}) {
282			t.Fatalf("new target history sample = %+v", events[1])
283		}
284		// The original sample is intact.
285		if !events[0].ObservedAt.Equal(targetSeen) || !sameValues(events[0].Values, wantHistory["target"][0].Values) {
286			t.Fatalf("original target history sample changed: %+v", events[0])
287		}
288	
289		// The other device keeps its own lastSeenAt, lastTelemetry and single
290		// history sample throughout; nothing on the target crossed over to it.
291		otherAfter := snapshot["other"]
292		if !otherAfter.LastSeenAt.Equal(otherSeen) {
293			t.Fatalf("other device lastSeenAt changed: %s -> %s", otherSeen, otherAfter.LastSeenAt)
294		}
295		if !sameValues(otherAfter.LastTelemetry, wantSnapshot["other"].LastTelemetry) {
296			t.Fatalf("other device lastTelemetry changed: %v -> %v", wantSnapshot["other"].LastTelemetry, otherAfter.LastTelemetry)
297		}
298		otherEvents := deviceHistory(t, h, "other")
299		if len(otherEvents) != 1 || otherEvents[0].Sequence != 1 ||
300			!otherEvents[0].ObservedAt.Equal(otherSeen) || !sameValues(otherEvents[0].Values, wantHistory["other"][0].Values) {
301			t.Fatalf("other device history changed: %+v", otherEvents)
302		}
303	}
